// 1. Pega o texto do CSV vindo do HTTP Request
const inputData = $input.first().json;
const csvTexto = typeof inputData === 'string' ? inputData : (inputData.data || '');

// 2. Converte o valor mínimo para número
function normalizarParaNumero(valor) {
  if (typeof valor === 'number') return valor;
  if (!valor) return 0;

  const textoLimpo = valor.toString().replace(/[R$\s]/g, '').trim();

  if (textoLimpo.includes(',')) {
    return parseFloat(textoLimpo.replace(/\./g, '').replace(',', '.')) || 0;
  }

  return parseFloat(textoLimpo) || 0;
}

// 3. Processa as linhas do CSV
const linhas = csvTexto.trim().split(/\r?\n/);
const listaInvestimentos = [];

for (let i = 1; i < linhas.length; i++) {
  const linhaAtual = linhas[i].trim();
  if (!linhaAtual) continue;

  const colunas = linhaAtual.split(',').map(c => c.trim());

  listaInvestimentos.push({
    perfil: colunas[0],
    produto: colunas[1],
    minimo: normalizarParaNumero(colunas[2]),
    rentabilidade: colunas[3]
  });
}

// 4. O SEGREDO DA AULA: Retornar 1 único item com a lista dentro de "investimentos"
return [
  {
    json: {
      investimentos: listaInvestimentos
    }
  }
];

// 1. Recupera os dados vindos do nó Merge
const dadosMerge = $input.first().json;
const clientes = dadosMerge.body?.clientes || [];
const catalogoInvestimentos = dadosMerge.investimentos || [];

// 2. Função auxiliar para converter "R$ 12.500,00" em 12500 (número)
function converterSaldoParaNumero(saldoStr) {
  if (typeof saldoStr === 'number') return saldoStr;
  if (!saldoStr) return 0;
  const textoLimpo = saldoStr.toString().replace(/[R$\s]/g, '').trim();
  return parseFloat(textoLimpo.replace(/\./g, '').replace(',', '.')) || 0;
}

// 3. Processa cada cliente e cruza com os investimentos
const resultados = [];

for (const cliente of clientes) {
  const saldoNum = converterSaldoParaNumero(cliente.saldo);

  // Filtra investimentos do mesmo perfil
  const investimentosPerfil = catalogoInvestimentos.filter(
    inv => inv.perfil.toLowerCase() === cliente.perfil.toLowerCase()
  );

  // Prioriza o investimento de maior valor mínimo que o saldo do cliente permite
  const opcoesValidas = investimentosPerfil
    .filter(inv => saldoNum >= inv.minimo)
    .sort((a, b) => b.minimo - a.minimo);

  let recomendacao = null;

  if (opcoesValidas.length > 0) {
    const escolhido = opcoesValidas[0];
    recomendacao = {
      perfil: escolhido.perfil,
      produto: escolhido.produto,
      minimo: escolhido.minimo,
      rentabilidade: escolhido.rentabilidade,
      motivo: "saldo_ok"
    };
  } else {
    // Caso o saldo seja inferior ao mínimo de todas as opções
    const maisAcessivel = [...investimentosPerfil].sort((a, b) => a.minimo - b.minimo)[0];
    recomendacao = {
      perfil: maisAcessivel.perfil,
      produto: maisAcessivel.produto,
      minimo: maisAcessivel.minimo,
      rentabilidade: maisAcessivel.rentabilidade,
      motivo: "saldo_insuficiente"
    };
  }

  // Formata o valor mínimo para exibição (ex: 1.000,00)
  const minimoFormatado = recomendacao.minimo.toLocaleString('pt-BR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });

  // 3 variações de mensagens
  const mensagens = [
    `Olá ${cliente.nome}! Pelo seu perfil [${cliente.perfil}], uma boa opção é **${recomendacao.produto}** (mínimo R$ ${minimoFormatado}). Com seu saldo atual (${cliente.saldo}), você já consegue investir. Rentabilidade: ${recomendacao.rentabilidade}.`,
    `${cliente.nome}! Recomendação para perfil [${cliente.perfil}]: **${recomendacao.produto}** (mínimo R$ ${minimoFormatado}). Seu saldo (${cliente.saldo}) já atende o mínimo. Rentabilidade: ${recomendacao.rentabilidade}.`,
    `${cliente.nome}, indo direto ao ponto: para o perfil [${cliente.perfil}], uma boa opção é **${recomendacao.produto}** (mínimo R$ ${minimoFormatado}). Você tem ${cliente.saldo}, então dá pra aplicar. Rentabilidade: ${recomendacao.rentabilidade}.`
  ];

  resultados.push({
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: cliente.saldo,
    saldo_num: saldoNum,
    recomendacao: recomendacao,
    mensagens: mensagens,
    mensagem_escolhida: mensagens[0]
  });
}

// 4. Retorna exatamente o formato esperado pela aula
return [
  {
    json: {
      ok: true,
      total_clientes: clientes.length,
      total_investimentos: catalogoInvestimentos.length,
      resultados: resultados
    }
  }
];

// 1. Obtém os resultados consolidados do nó anterior
const resultados = $json.resultados || [];

// 2. Função de segurança para garantir a conversão do saldo
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// 3. Retorna UM ITEM por cliente (10 itens na saída)
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  // Seleciona a mensagem mais direta ou a escolhida
  const mensagemBase = c.mensagens?.[2] || c.mensagem_escolhida || (c.mensagens && c.mensagens[0]) || "";

  return {
    json: {
      email_to: c.email,
      name: c.nome,
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: {
        perfil: c.recomendacao?.perfil,
        produto: c.recomendacao?.produto,
        minimo: c.recomendacao?.minimo,
        rentabilidade: c.recomendacao?.rentabilidade
      },
      motivo: c.recomendacao?.motivo || "saldo_ok",
      mensagem_base: mensagemBase,
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: [
          "promessas de ganho",
          "gerundios",
          "linguagem agressiva"
        ]
      }
    }
  };
});

return out;

