// 1. Pega os itens retornados pela IA e os dados originais do briefing
const itensIA = $input.all();
const itensBriefing = $('Code in JavaScript2').all();

// 2. Função auxiliar para extrair o texto da resposta da IA (funciona com Gemini ou OpenAI)
function obterTextoDaIA(json) {
  if (typeof json === 'string') return json;
  if (json.text) return json.text;
  if (json.output?.content?.[0]?.text) return json.output.content[0].text;
  if (json.content?.parts?.[0]?.text) return json.content.parts[0].text;
  if (json.candidates?.[0]?.content?.parts?.[0]?.text) return json.candidates[0].content.parts[0].text;
  if (json.message?.content) return json.message.content;
  if (typeof json.output === 'string') return json.output;
  return JSON.stringify(json);
}

// 3. Função para fazer parse do JSON retornado pela IA (removendo blocos de markdown ```json se houver)
function parseRespostaJSON(texto) {
  if (!texto) return {};
  if (typeof texto === 'object') return texto;

  const limpo = texto
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  try {
    return JSON.parse(limpo);
  } catch (e) {
    const match = limpo.match(/\{[\s\S]*\}/);
    if (match) {
      try { return JSON.parse(match[0]); } catch (err) {}
    }
    return {
      subject: "Oportunidade de Investimento",
      text_body: texto,
      html_body: `<p>${texto.replace(/\n/g, '<br>')}</p>`
    };
  }
}

// 4. Mapeia cada cliente com o e-mail gerado e os metadados (exatamente como na aula)
return itensIA.map((item, index) => {
  const j = itensBriefing[index]?.json || {};
  const textoLLM = obterTextoDaIA(item.json);
  const parsed = parseRespostaJSON(textoLLM);

  const to = j.email_to || j.email || "";
  const subject = parsed.subject || "Sugestão de Investimento";
  const text_body = parsed.text_body || textoLLM;
  const html_body = parsed.html_body || `<p>${text_body}</p>`;

  return {
    json: {
      ok: true,
      to: to,
      subject: subject,
      text_body: text_body,
      html_body: html_body,

      // (opcional) manter alguns campos úteis pra debug/aula
      meta: {
        name: j.name,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo
      }
    }
  };
});
